package cn.courselens;
import android.app.*;import android.content.*;import android.database.*;import android.net.Uri;import android.provider.CalendarContract;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;import static org.robolectric.util.ReflectionHelpers.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class AiPhoneContextTest {
 @Test public void phoneSourcesAreUnavailableUntilEnabledAndAuthorized()throws Exception{Context c=RuntimeEnvironment.getApplication();assertFalse(AiPhoneContext.calendar(c).getBoolean("available"));assertFalse(AiNotificationListener.snapshot(c).getBoolean("available"));AiPhoneContext.settings(c).edit().putBoolean("calendar",true).putBoolean("notifications",true).commit();org.robolectric.Shadows.shadowOf((Application)c).denyPermissions(android.Manifest.permission.READ_CALENDAR);assertFalse(AiPhoneContext.calendar(c).getBoolean("available"));assertFalse(AiNotificationListener.snapshot(c).getBoolean("available"));}
 @Test public void calendarIsLimitedAndDeclaresItsRange()throws Exception{Context c=RuntimeEnvironment.getApplication();AiPhoneContext.settings(c).edit().putBoolean("calendar",true).commit();org.robolectric.Shadows.shadowOf((Application)c).grantPermissions(android.Manifest.permission.READ_CALENDAR);ContentProvider provider=new ContentProvider(){public boolean onCreate(){return true;}public Cursor query(Uri u,String[] columns,String selection,String[] args,String sort){MatrixCursor cursor=new MatrixCursor(columns);for(int i=0;i<101;i++)cursor.addRow(new Object[]{"合成日程 "+i,1000L,2000L,"合成地点",0});return cursor;}public String getType(Uri u){return null;}public Uri insert(Uri u,ContentValues values){return null;}public int delete(Uri u,String w,String[] a){return 0;}public int update(Uri u,ContentValues v,String w,String[] a){return 0;}};org.robolectric.shadows.ShadowContentResolver.registerProviderInternal(CalendarContract.AUTHORITY,provider);JSONObject result=AiPhoneContext.calendar(c);assertTrue(result.getBoolean("available"));assertEquals(100,result.getJSONArray("events").length());assertTrue(result.getBoolean("truncated"));assertTrue(result.getLong("until_epoch_ms")>result.getLong("from_epoch_ms"));}
 @Test public void screenFramesAreSessionOnlyAndClearedOnStop()throws Exception{AiScreenService.active=false;setStaticField(AiScreenService.class,"latest",new byte[]{1,2,3});assertNull(AiScreenService.frame());AiScreenService.active=true;assertNotNull(AiScreenService.frame());org.robolectric.android.controller.ServiceController<AiScreenService> service=Robolectric.buildService(AiScreenService.class).create();service.destroy();assertFalse(AiScreenService.active);assertNull(AiScreenService.frame());}
}
